<script>
(()=>{const city=document.getElementById('hotel-city'),district=document.getElementById('hotel-district');if(!city||!district)return;const old=district.value;function filter(){const id=city.value;let first=null;[...district.options].forEach((o,i)=>{if(i===0)return;const show=o.dataset.city===id;o.hidden=!show;o.disabled=!show;if(show&&!first)first=o});if(!district.value||district.selectedOptions[0]?.disabled)district.value=first?.value||'';if(!first)district.value='';}city.addEventListener('change',filter);filter();if(old&&[...district.options].some(o=>o.value===old&&o.dataset.city===city.value))district.value=old;})();
</script>
